  ?bom pv:hasBomPart ?part .
  ?part pv:hasSupplier ?supplier .
  ?supplier pv:country ontology:Country .
}

training-free.sparql:
SELECT ?bom ?bomName
WHERE {
  ?bom a pv:BillOfMaterial ;
       pv:name ?bomName ;
       pv:hasBomPart ?part .
  ?part pv:hasSupplier ?supplier .
  ?supplier pv:country ontology:Country ;
          pv:name ?supplierName .
  FILTER(?supplierName = "Poland")
}
ORDER BY ?bomName
LIMIT 10

SELECT ?bom ?averageCost
WHERE {
  ?bom a pv:BillOfMaterial ;
       pv:hasBomPart ?part .
  ?part a pv:BomPart ;
        pv:hasSupplier ?supplier .
  ?supplier pv:price ?price .
  BIND(?price AS ?unitCost)
}
GROUP BY ?bom
ORDER BY DESC(?averageCost)
LIMIT 1
